+      const fileMatch = patch.match(/^\+\+\+ b\/(.+)$/m);
+      const file = fileMatch ? fileMatch[1] : primaryFile;
+      
+      // Avoid duplicates
+      if (!patches.some(p => p.patch === patch)) {
+        patches.push({ file, patch });
+      }
+    }
