+      while ((match = hunkRegex.exec(output)) !== null) {
+        const hunk = match[0];
+        // Check if this looks like actual diff content
+        if (hunk.includes('\n-') || hunk.includes('\n+')) {
+          const patch = `--- a/${primaryFile}\n+++ b/${primaryFile}\n${hunk}`;
+          patches.push({ file: primaryFile, patch });
+        }
+      }
+    }
