+    const patchFailedMatch = errorOutput.match(/error: patch failed: .+?:(\d+)/);
+    if (patchFailedMatch) {
+      result.errorType = 'line_mismatch';
+      result.lineNumber = parseInt(patchFailedMatch[1], 10);
